<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/functions.php';require_role('werkgever');$pageTitle='Werkgeversdashboard';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['create_job'])){
    $title=trim($_POST['title']??'');$category=$_POST['category']??'';$location=trim($_POST['location']??'');$wage=str_replace(',','.',trim($_POST['hourly_wage']??''));$hours=trim($_POST['hours_per_week']??'');$minAge=filter_var($_POST['min_age']??18,FILTER_VALIDATE_INT);$maxAge=trim($_POST['max_age']??'');$schedule=trim($_POST['schedule']??'');$description=trim($_POST['description']??'');$responsibilities=trim($_POST['responsibilities']??'');$requirements=trim($_POST['requirements']??'');$icon=$_POST['icon']??'💼';
    if(mb_strlen($title)<3||mb_strlen($location)<2||mb_strlen($description)<20){$error='Vul een functietitel, locatie en beschrijving van minimaal 20 tekens in.';}
    elseif(!in_array($category,['Horeca','Winkel','Zorg','Onderwijs','Kantoor','Overig'],true)){$error='Kies een geldige categorie.';}
    elseif(!is_numeric($wage)||(float)$wage<=0||(float)$wage>500){$error='Vul een geldig bruto uurloon in.';}
    elseif(!is_numeric($hours)||(float)$hours<=0||(float)$hours>80){$error='Vul een geldig aantal uren per week in.';}
    elseif($minAge===false||$minAge<13||$minAge>100){$error='Vul een geldige minimumleeftijd in.';}
    elseif($maxAge!==''&&(!ctype_digit($maxAge)||(int)$maxAge<$minAge||(int)$maxAge>100)){$error='De maximumleeftijd moet hoger zijn dan de minimumleeftijd.';}
    else{$stmt=$pdo->prepare("INSERT INTO jobs(employer_id,title,category,location,hourly_wage,hours_per_week,min_age,max_age,schedule,description,responsibilities,requirements,icon,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,'published')");$stmt->execute([$_SESSION['user_id'],$title,$category,$location,(float)$wage,(float)$hours,$minAge,$maxAge===''?null:(int)$maxAge,$schedule,$description,$responsibilities,$requirements,$icon]);$success='Je vacature is gepubliceerd.';}
}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete_job'])){$jobId=filter_var($_POST['job_id']??0,FILTER_VALIDATE_INT);$stmt=$pdo->prepare("UPDATE jobs SET status='closed' WHERE id=? AND employer_id=?");$stmt->execute([$jobId,$_SESSION['user_id']]);$success='De vacature is gesloten.';}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['update_application'])){$appId=filter_var($_POST['application_id']??0,FILTER_VALIDATE_INT);$status=$_POST['status']??'';if(in_array($status,['received','reviewing','accepted','rejected'],true)){$stmt=$pdo->prepare("UPDATE applications a JOIN jobs j ON j.id=a.job_id SET a.status=? WHERE a.id=? AND j.employer_id=?");$stmt->execute([$status,$appId,$_SESSION['user_id']]);$success='De status van de sollicitatie is bijgewerkt.';}}
$stmt=$pdo->prepare("SELECT j.*, (SELECT COUNT(*) FROM applications a WHERE a.job_id=j.id) AS application_count FROM jobs j WHERE j.employer_id=? ORDER BY j.created_at DESC");$stmt->execute([$_SESSION['user_id']]);$jobs=$stmt->fetchAll();
$stmt=$pdo->prepare("SELECT a.id AS application_id,a.status,a.created_at,a.cover_letter,u.name AS applicant_name,u.email AS applicant_email,j.title,j.id AS job_id FROM applications a JOIN jobs j ON j.id=a.job_id JOIN users u ON u.id=a.user_id WHERE j.employer_id=? ORDER BY a.created_at DESC");$stmt->execute([$_SESSION['user_id']]);$applications=$stmt->fetchAll();
include __DIR__.'/includes/header.php';?>
<section class="page-intro"><div class="container"><span class="eyebrow">Werkgeversomgeving</span><h1>Vind jouw volgende collega.</h1><p>Publiceer vacatures voor studenten en houd sollicitaties bij.</p></div></section><section class="content-section"><div class="container">
<?php if($error): ?><div class="form-error"><?= e($error) ?></div><?php endif; ?><?php if($success): ?><div class="form-success"><?= e($success) ?></div><?php endif; ?>
<div class="dashboard-grid"><div class="metric"><span>Totaal vacatures</span><strong><?= count($jobs) ?></strong></div><div class="metric"><span>Sollicitaties ontvangen</span><strong><?= count($applications) ?></strong></div><div class="metric"><span>Actieve vacatures</span><strong><?= count(array_filter($jobs,fn($j)=>$j['status']==='published')) ?></strong></div></div>
<div class="two-column"><div class="panel"><div class="panel-title"><h2>Jouw vacatures</h2><span class="tag"><?= count($jobs) ?> totaal</span></div><?php if($jobs): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Vacature</th><th>Status</th><th>Sollicitaties</th><th>Actie</th></tr></thead><tbody><?php foreach($jobs as $j): ?><tr><td><a class="text-link" href="vacature.php?id=<?= (int)$j['id'] ?>"><?= e($j['title']) ?></a><br><span class="job-meta"><?= e($j['location']) ?></span></td><td><?= $j['status']==='published'?'Gepubliceerd':'Gesloten' ?></td><td><?= (int)$j['application_count'] ?></td><td><?php if($j['status']==='published'): ?><form method="post" class="inline-form"><input type="hidden" name="job_id" value="<?= (int)$j['id'] ?>"><button class="small-button danger" name="delete_job" value="1" data-confirm="Weet je zeker dat je deze vacature wilt sluiten?">Sluiten</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="job-meta">Je hebt nog geen vacatures geplaatst.</p><?php endif; ?></div>
<div class="panel"><h2>Nieuwe vacature plaatsen</h2><form class="form-stack" method="post"><div class="field"><label for="title">Functietitel</label><input id="title" name="title" required maxlength="120" placeholder="Bijv. winkelmedewerker"></div><div class="field"><label for="category">Categorie</label><select id="category" name="category"><?php foreach(['Horeca','Winkel','Zorg','Onderwijs','Kantoor','Overig'] as $c): ?><option><?= e($c) ?></option><?php endforeach; ?></select></div><div class="field"><label for="location">Locatie</label><input id="location" name="location" required placeholder="Bijv. Arnhem"></div><div class="field"><label for="hourly_wage">Bruto uurloon (€)</label><input id="hourly_wage" name="hourly_wage" type="number" min=".01" max="500" step=".01" required></div><div class="field"><label for="hours_per_week">Uren per week</label><input id="hours_per_week" name="hours_per_week" type="number" min=".5" max="80" step=".5" required></div><div class="field"><label for="min_age">Minimumleeftijd</label><input id="min_age" name="min_age" type="number" min="13" max="100" value="16" required></div><div class="field"><label for="max_age">Maximumleeftijd (optioneel)</label><input id="max_age" name="max_age" type="number" min="13" max="100"></div><div class="field"><label for="schedule">Werktijden</label><input id="schedule" name="schedule" placeholder="Bijv. avonden en weekenden"></div><div class="field"><label for="icon">Vacature-icoon</label><select id="icon" name="icon"><option>💼</option><option>☕</option><option>🛒</option><option>🧸</option><option>🍽️</option><option>📦</option><option>💻</option></select></div><div class="field"><label for="description">Vacaturebeschrijving</label><textarea id="description" name="description" rows="5" minlength="20" required placeholder="Beschrijf de functie en het bedrijf."></textarea></div><div class="field"><label for="responsibilities">Werkzaamheden</label><textarea id="responsibilities" name="responsibilities" rows="3"></textarea></div><div class="field"><label for="requirements">Eisen en voorwaarden</label><textarea id="requirements" name="requirements" rows="3"></textarea></div><button class="button" type="submit" name="create_job" value="1">Vacature publiceren</button></form></div></div>
<div class="panel" style="margin-top:25px"><div class="panel-title"><h2>Sollicitaties</h2><span class="tag"><?= count($applications) ?> ontvangen</span></div><?php if($applications): ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Kandidaat</th><th>Vacature</th><th>Motivatie</th><th>Status</th><th>Bijwerken</th></tr></thead><tbody><?php foreach($applications as $a): ?><tr><td><?= e($a['applicant_name']) ?><br><span class="job-meta"><?= e($a['applicant_email']) ?></span></td><td><?= e($a['title']) ?></td><td><?= e($a['cover_letter']?:'Geen motivatie toegevoegd.') ?></td><td><?= e(['received'=>'Ontvangen','reviewing'=>'In behandeling','accepted'=>'Aangenomen','rejected'=>'Afgewezen'][$a['status']]??$a['status']) ?></td><td><form method="post" class="action-row"><input type="hidden" name="application_id" value="<?= (int)$a['application_id'] ?>"><select name="status" aria-label="Sollicitatiestatus"><option value="received" <?= $a['status']==='received'?'selected':'' ?>>Ontvangen</option><option value="reviewing" <?= $a['status']==='reviewing'?'selected':'' ?>>In behandeling</option><option value="accepted" <?= $a['status']==='accepted'?'selected':'' ?>>Aangenomen</option><option value="rejected" <?= $a['status']==='rejected'?'selected':'' ?>>Afgewezen</option></select><button class="small-button" name="update_application" value="1">Opslaan</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="job-meta">Sollicitaties verschijnen hier zodra studenten reageren.</p><?php endif; ?></div>
</div></section><?php include __DIR__.'/includes/footer.php'; ?>
